const crypto = require('crypto');
const input = $input.first().json;
const secret = $env.ODIN_HMAC_SECRET || 'odin-default-production-hmac-secret-key-32';
const webhookBaseUrl = $env.ODIN_WEBHOOK_BASE_URL || 'https://n8n.yourdomain.com';
const actionId = `act_${Date.now()}`;
const expiresAt = Date.now() + 15 * 60 * 1000;

const payload = JSON.stringify({
  actionId,
  incidentId: input.incidentId,
  actionType: input.recommendedAction?.type,
  service: input.service,
  expiresAt
});

const payloadBase64 = Buffer.from(payload).toString('base64url');
const signature = crypto.createHmac('sha256', secret).update(payloadBase64).digest('base64url');
const token = `${payloadBase64}.${signature}`;

const approveUrl = `${webhookBaseUrl}/webhook/odin-approval?token=${encodeURIComponent(token)}&decision=approve`;
const rejectUrl = `${webhookBaseUrl}/webhook/odin-approval?token=${encodeURIComponent(token)}&decision=reject`;

const brandName = $env.ODIN_BRAND_NAME || 'Odin SRE Bot';
const brandColor = $env.ODIN_BRAND_COLOR || '#0284c7';
const toEmail = $env.ODIN_NOTIFY_EMAIL || 'devops@yourdomain.com';

const htmlBody = `
<!DOCTYPE html>
<html>
<body style="font-family:sans-serif; background:#f8fafc; padding:20px;">
  <div style="max-width:550px; margin:0 auto; background:#ffffff; border-radius:8px; border:1px solid #e2e8f0; padding:24px;">
    <h2 style="color:${brandColor}; margin-top:0;">${brandName} Approval Gate</h2>
    <p><strong>Severity:</strong> ${input.severity}</p>
    <p><strong>Service:</strong> ${input.service}</p>
    <p><strong>Root Cause:</strong> ${input.rootCause}</p>
    <p><strong>Proposed Action:</strong> ${input.recommendedAction?.type}</p>
    <div style="margin-top:24px;">
      <a href="${approveUrl}" style="background:#16a34a; color:#ffffff; padding:10px 18px; text-decoration:none; border-radius:5px; font-weight:bold;">Approve Action</a>
      &nbsp;&nbsp;
      <a href="${rejectUrl}" style="background:#64748b; color:#ffffff; padding:10px 18px; text-decoration:none; border-radius:5px; font-weight:bold;">Reject</a>
    </div>
    <p style="font-size:11px; color:#94a3b8; margin-top:24px;">Link expires in 15 minutes.</p>
  </div>
</body>
</html>`;

return [{
  json: {
    incidentId: input.incidentId,
    token,
    approveUrl,
    rejectUrl,
    toEmail,
    htmlBody,
    subject: `[APPROVAL REQUIRED] ${input.severity} - ${input.service}`
  }
}];

const crypto = require('crypto');
const query = $input.first().json.query || {};
const token = query.token || '';
const decision = query.decision || 'reject';
const secret = $env.ODIN_HMAC_SECRET || 'odin-default-production-hmac-secret-key-32';

if (!token || !token.includes('.')) {
  return [{ json: { valid: false, message: 'Invalid or missing security token', html: '<h2>Invalid Token</h2>' } }];
}

const [payloadBase64, providedSig] = token.split('.');
const expectedSig = crypto.createHmac('sha256', secret).update(payloadBase64).digest('base64url');

if (providedSig !== expectedSig) {
  return [{ json: { valid: false, message: 'Cryptographic signature mismatch', html: '<h2>Signature Verification Failed</h2>' } }];
}

let data = {};
try {
  data = JSON.parse(Buffer.from(payloadBase64, 'base64url').toString('utf8'));
} catch {
  return [{ json: { valid: false, message: 'Corrupt payload', html: '<h2>Corrupt Token</h2>' } }];
}

if (Date.now() > data.expiresAt) {
  return [{ json: { valid: false, message: 'Token expired', html: '<h2>Approval Link Expired</h2>' } }];
}

const approved = decision === 'approve';
const html = approved
  ? '<h2 style="color:#16a34a;">Action Approved</h2><p>Remediation has been triggered for ' + data.service + '.</p>'
  : '<h2 style="color:#dc2626;">Action Rejected</h2><p>Remediation was declined by operator.</p>';

return [{
  json: {
    valid: true,
    approved,
    actionType: data.actionType,
    service: data.service,
    incidentId: data.incidentId,
    html
  }
}];
